/// <summary>
/// One response shape for HSMobileOpsFeedbackService.
/// </summary>
[DataContractAttribute]
class HSMobileOpsFeedbackResponse
{
    boolean success;
    str errorCode;
    str message;
    boolean alreadyCreated;
    List items;
}

Method.Source:
